import Vue from 'vue'
import VueRouter from 'vue-router'
Vue.use(VueRouter);

var router = new VueRouter({
    routes: [
        {
            path: '/',
            meta: { isAuth: true, title: '/' },
        },
        {
            path: '/ct',
            name: 'ct',
            meta: { isAuth: true, title: 'ct' },
            component: () => import('../components/ct.vue'), // vue路由懒加载  异步加载

        },
        {
            path: '/home-zh',
            name: 'home-zh',
            meta: { isAuth: true, title: 'home-zh' },
            component: () => import('../components/Home_zh.vue'), // vue路由懒加载  异步加载
        },
        {
            path: '/home-en',
            name: 'home-en',
            meta: { isAuth: true, title: 'home-en' },
            component: () => import('../components/Home_en.vue'), // vue路由懒加载  异步加载

        },
        {
            path: '*',
            redirect: '/home-zh'
          }
    ]
});

//全局前置路由守卫————初始化的时候被调用、每次路由切换之前被调用
// 定义需要认证的路由名称白名单
const AUTH_WHITELIST = ['home-zh', 'home-en', 'ct'];

router.beforeEach((to, from, next) => {
    // 不需要认证的路由直接放行
    if (!to.meta.isAuth) return next();
    
    // 根路径重定向
    if (to.path === '/') {
        const languagePath = localStorage.getItem('languageSet') === 'en' 
            ? '/home-en' 
            : '/home-zh';
        return next({ path: languagePath });
    }
    
    // 白名单路由放行
    if (AUTH_WHITELIST.includes(to.name)) {
        return next();
    }
    
    // 默认放行（或可根据需要添加其他逻辑如重定向到登录页）
    next();
});
    export default router;
